style.css:
@-moz-document domain("claude.ai") {
/* ============================= */
/*      Farsi Font               */
/* ============================= */
@font-face {
  font-family: 'Vazirmatn';
  src:
    local('Vazirmatn'),
    url('https://fonts.gstatic.com/s/vazirmatn/v13/Dxx78j6PP2D_kU2muijPEKnp1_s.woff2') format('woff2');
}

body, input, textarea, button {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
}

/* User messages font */
[data-testid="user-message"],
[data-testid="user-message"] p,
[data-testid="user-message"] li,
[data-testid="user-message"] span {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
}

/* Claude response font — direction is auto-detected per element */
.font-claude-response-body,
.font-claude-response-body p,
.font-claude-response-body li,
.font-claude-response-body blockquote {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
  unicode-bidi: plaintext !important;
  text-align: start !important;
  /* NO direction: rtl here — browser detects Farsi vs English automatically */
}

/* Claude response headings */
.standard-markdown h1,
.standard-markdown h2,
.standard-markdown h3,
.standard-markdown h4,
.standard-markdown h5,
.standard-markdown h6 {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
  unicode-bidi: plaintext !important;
  text-align: start !important;
}

/* Claude response tables */
.standard-markdown table,
.standard-markdown thead,
.standard-markdown tbody,
.standard-markdown tr,
.standard-markdown th,
.standard-markdown td {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
  unicode-bidi: plaintext !important;
  text-align: start !important;
}

/* ============================= */
/*      Smart RTL                */
/* ============================= */

/* Input box - Main div */
.tiptap.ProseMirror {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
  unicode-bidi: plaintext !important;
  text-align: start !important;
  /* direction is auto-detected from what the user types */
}

/* Input box - paragraph */
.tiptap.ProseMirror p {
  font-family: 'Vazirmatn', -apple-system, BlinkMacSystemFont, sans-serif !important;
  unicode-bidi: plaintext !important;
  text-align: start !important;
}

/* User messages */
[data-testid="user-message"] p,
[data-testid="user-message"] li {
  unicode-bidi: plaintext !important;
  text-align: start !important;
  /* direction auto-detected per paragraph */
}

/* Code blocks - always LTR */
pre, code,
.font-claude-response-body pre,
.font-claude-response-body code,
.standard-markdown pre,
.standard-markdown code {
  direction: ltr !important;
  text-align: left !important;
  unicode-bidi: isolate !important;
  font-family: monospace !important;
}
}
